@sig trait RequestActionEligibility_Api {
  def id: Art.BridgeId
  def admission_decision_Id : Art.PortId
  def request_proposal_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var request_proposal: Mining_Cargo_Transfer_Evidence_Coordinator.ActionProposal = $

  def put_request_proposal(value : Mining_Cargo_Transfer_Evidence_Coordinator.ActionProposal) : Unit = {
    Contract(
      Modifies(request_proposal),
      Ensures(
        request_proposal == value
      )
    )
    Spec {
      request_proposal = value
    }

    Art.putValue(request_proposal_Id, Mining_Cargo_Transfer_Evidence_Coordinator.ActionProposal_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class RequestActionEligibility_Initialization_Api (
  val id: Art.BridgeId,
  val admission_decision_Id : Art.PortId,
  val request_proposal_Id : Art.PortId) extends RequestActionEligibility_Api

@datatype class RequestActionEligibility_Operational_Api (
  val id: Art.BridgeId,
  val admission_decision_Id : Art.PortId,
  val request_proposal_Id : Art.PortId) extends RequestActionEligibility_Api {

  // Logika spec var representing port state for incoming data port
  @spec var admission_decision: Mining_Cargo_Transfer_Evidence_Coordinator.AdmissionDecision = $

  def get_admission_decision() : Option[Mining_Cargo_Transfer_Evidence_Coordinator.AdmissionDecision] = {
    Contract(
      Ensures(
        Res == Some(admission_decision)
      )
    )
    val value : Option[Mining_Cargo_Transfer_Evidence_Coordinator.AdmissionDecision] = Art.getValue(admission_decision_Id) match {
      case Some(Mining_Cargo_Transfer_Evidence_Coordinator.AdmissionDecision_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port admission_decision.  Expecting 'Mining_Cargo_Transfer_Evidence_Coordinator.AdmissionDecision_Payload' but received ${v}")
        None[Mining_Cargo_Transfer_Evidence_Coordinator.AdmissionDecision]()
      case _ => None[Mining_Cargo_Transfer_Evidence_Coordinator.AdmissionDecision]()
    }
    return value
  }
}
